import subprocess


class LeftStrippedDict(dict):
    def get(self, k):
        if isinstance(k, str):
            k = k.lstrip()
        return super(LeftStrippedDict, self).get(k)

    def __getitem__(self, k):
        if isinstance(k, str):
            k = k.lstrip()
        return super(LeftStrippedDict, self).__getitem__(k)

    def __contains__(self, k):
        if isinstance(k, str):
            k = k.lstrip()
        return super(LeftStrippedDict, self).__contains__(k)


lambda_comparisons = LeftStrippedDict({
    '==': lambda a, b: a == b,
    '!=': lambda a, b: a != b,
    '>=': lambda a, b: a >= b,
    '<=': lambda a, b: a <= b,
})


def initialize_default(variable, default_value):
    return variable if variable else default_value


def get_nested_element(dictionary, path):
    for item in path.split("/"):
        dictionary = dictionary[item]
    return dictionary


def find_all_key_values(dictionary, key):
    return unpack_recursively(list(_all_keys_iterator(dictionary, key)))


def _all_keys_iterator(dictionary_, key):
    try:
        yield dictionary_[key]
    except KeyError:
        for v in dictionary_.values():
            if isinstance(v, dict):
                yield list(_all_keys_iterator(v, key))


def unpack_recursively(data):
    output = []

    def unpack(datalist):
        for i in datalist:
            if isinstance(i, list):
                unpack(datalist)
            else:
                output.append(i)

    unpack(data)
    return output


def dict_to_str_with_assigment_sign(dict_):
    if isinstance(dict_, dict):
        return ", ".join('{}={!r}'.format(key, val) for key, val in sorted(dict_.items()))
    else:
        raise TypeError('Not dictionary object')


class Ip:
    def __init__(self, eth_name, remote_host='127.0.0.1'):
        self.eth_name = eth_name
        self.remote_host = remote_host

    @property
    def address(self):
        return self._get_ip_address_from_communication_data(self._communicate())

    def _communicate(self):
        return subprocess.Popen(
            [
                r"ssh {0} ip address show label {1} | grep 'inet ' | head -n1 | "
                r"sed -r 's:.*inet (.+?)/.*:\1:'".format(self.remote_host, self.eth_name)
            ],
            shell=True,
            stdout=subprocess.PIPE,
        ).communicate()

    @staticmethod
    def _get_ip_address_from_communication_data(data):
        return data[0].decode("utf-8").strip()


def get_eth_ip(eth_name, remote_host='127.0.0.1'):
    return Ip(eth_name, remote_host).address
